"""Voice-Controlled Smart Car Controller (PC)"""
import requests
import speech_recognition as sr

ESP_IP = "192.168.0.50"  # ESP32 IP
CMD_URL = f"http://{ESP_IP}:8080/ai"

r = sr.Recognizer()
mic = sr.Microphone()

with mic as source:
    r.adjust_for_ambient_noise(source)

while True:
    with mic as source:
        audio = r.listen(source)
    try:
        text = r.recognize_google(audio, language="en-US").lower()
        print("Voice:", text)

        action = None
        if any(w in text for w in ("forward", "go")):
            action = "GO"
        elif any(w in text for w in ("back", "reverse")):
            action = "BACK"
        elif "left" in text:
            action = "LEFT"
        elif "right" in text:
            action = "RIGHT"
        elif "stop" in text:
            action = "STOP"
        elif "dance" in text:
            action = "DANCE"

        if action:
            requests.get(CMD_URL, params={"action": action}, timeout=0.5)
    except sr.UnknownValueError:
        pass
